//! Host-reference and VM execution tests for the ethrex stateless guest.
//!
//! Fixtures are generated by `tooling/ethrex-fixtures`; the guest ELF comes
//! from `make compile-programs`. See `executor/tests/README.md`.

use ethrex_guest_program::crypto::NativeCrypto;
use ethrex_guest_program::l1::run_stateless_guest;
use executor::elf::Elf;
use executor::vm::execution::{Executor, ExecutorError, ReturnValues};
use std::sync::Arc;

fn run_program_without_expect(
    elf_path: &str,
    private_inputs: Vec<u8>,
) -> Result<ReturnValues, ExecutorError> {
    println!("Testing {elf_path}");
    let elf_data = std::fs::read(elf_path).unwrap();
    let program = Elf::load(&elf_data).unwrap();
    println!("Program entry: 0x{:016x}", program.entry_point);
    let mut executor = Executor::new(&program, private_inputs)?;
    while let Some(_logs) = executor.resume()? {}
    executor.finish()
}

fn native_output(inputs: &[u8]) -> Vec<u8> {
    let output = run_stateless_guest(inputs, Arc::new(NativeCrypto));
    assert_eq!(output.len(), 43, "unexpected stateless output length");
    assert_eq!(output[32], 1, "native stateless validation failed");
    output
}

fn run_fixture(name: &str) {
    let inputs = std::fs::read(format!("{FIXTURES_DIR}/{name}")).unwrap();
    let output = native_output(&inputs);
    let result = run_program_without_expect(ELF_PATH, inputs).expect("failed to run guest ELF");
    assert_eq!(result.memory_values, output);
}

const ELF_PATH: &str = "../../executor/program_artifacts/rust/ethrex.elf";
const FIXTURES_DIR: &str = "../../executor/tests";

/// Larger-block smoke test: a synthetic ethrex block with 10 ETH transfers.
#[ignore = "heavier synthetic block; run in the dedicated ignored CI step"]
#[test]
fn test_ethrex() {
    run_fixture("ethrex_10_transfers.bin");
}

#[test]
fn test_ethrex_simple_tx() {
    run_fixture("ethrex_simple_tx.bin");
}

#[test]
fn test_ethrex_empty_block() {
    run_fixture("ethrex_empty_block.bin");
}

const REAL_BLOCK_FIXTURE: &str = "ethrex_mainnet_25453112.bin";

/// Host-only acceptance gate for the real SSZ stateless fixture produced by
/// `tooling/ethrex-fixtures --bin real_block`. The fixture name is pinned here
/// as well as in the Makefile, so repointing the block needs both edits; a
/// missed one fails loudly on the missing file rather than proving less.
#[test]
fn test_ethrex_real_block_native() {
    let inputs = std::fs::read(format!("{FIXTURES_DIR}/{REAL_BLOCK_FIXTURE}")).unwrap();
    native_output(&inputs);
}

/// The dependency graph intentionally has no KZG backend. Keep this check so
/// a future feature change cannot silently make the guest and host precompile
/// surfaces diverge.
#[test]
fn no_kzg_backend_linked() {
    use ethrex_guest_program::crypto::Crypto;

    let result = NativeCrypto.verify_kzg_proof(&[0u8; 32], &[0u8; 32], &[0u8; 48], &[0u8; 48]);
    let message = match result {
        Ok(()) => "verify_kzg_proof accepted zero input".to_string(),
        Err(err) => format!("{err:?}"),
    };
    assert!(
        message.contains("One of features c-kzg or kzg-rs should be active"),
        "a KZG backend is linked into ethrex-tests: {message}"
    );
}

#[ignore = "real block through the VM; unmeasured runtime"]
#[test]
fn test_ethrex_real_block_vm() {
    run_fixture(REAL_BLOCK_FIXTURE);
}
